/* Token Radar — a dark editorial page.
   Palette: near-black ink, a warm gold accent, mint for growth and a muted red for drawdowns.
   Type: a serif display for headlines, a humanist sans for prose, a mono for every figure.
   Spacing runs on one scale; every surface is a hairline, a radius and a shadow. */

:root {
  --bg: #090c11;
  --bg-2: #0d1219;
  --panel: #111823;
  --panel-2: #16202d;
  --panel-3: #1b2634;
  --ink: #eef3f9;
  --ink-2: #c3cedb;
  --muted: #8b99ab;
  --faint: #5c6a7d;
  --line: #202b39;
  --line-2: #2c394a;
  --gold: #f2c15c;
  --gold-soft: rgba(242, 193, 92, 0.12);
  --gold-line: rgba(242, 193, 92, 0.32);
  --mint: #67e0bd;
  --mint-soft: rgba(103, 224, 189, 0.12);
  --red: #ff7f8a;
  --red-soft: rgba(255, 127, 138, 0.12);
  --blue: #85b8ff;
  --radius-lg: 16px;
  --radius: 11px;
  --radius-sm: 8px;
  --shadow: 0 30px 80px rgba(0, 0, 0, 0.45);
  --font-display: Georgia, "Times New Roman", serif;
  --font-body: ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-mono: ui-monospace, "SFMono-Regular", Menlo, Consolas, "Liberation Mono", monospace;
  --s1: 4px;
  --s2: 8px;
  --s3: 12px;
  --s4: 16px;
  --s5: 24px;
  --s6: 32px;
  --s7: 48px;
  --s8: 64px;
  --maxw: 1280px;
}

* { box-sizing: border-box; }
html { color-scheme: dark; scroll-behavior: smooth; }
body {
  margin: 0;
  min-height: 100vh;
  background:
    radial-gradient(1100px 560px at 82% -12%, rgba(242, 193, 92, 0.09), transparent 62%),
    radial-gradient(900px 520px at -8% 2%, rgba(103, 224, 189, 0.06), transparent 58%),
    var(--bg);
  color: var(--ink);
  font: 400 15px/1.55 var(--font-body);
  text-wrap: pretty;
  -webkit-font-smoothing: antialiased;
}
h1, h2, h3, h4 { margin: 0; text-wrap: balance; }
h1, h2 { font-family: var(--font-display); font-weight: 500; letter-spacing: -0.02em; }
h3, h4 { font-family: var(--font-body); font-weight: 600; letter-spacing: -0.01em; }
p { margin: 0; }
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
a { color: var(--gold); }

.skip {
  position: absolute; left: -9999px; top: 0; z-index: 50;
  padding: var(--s2) var(--s4); background: var(--gold); color: #141008;
  border-radius: var(--radius-sm); font-weight: 600;
}
.skip:focus { left: var(--s4); top: var(--s4); }
:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }
.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}

.shell { max-width: var(--maxw); margin: 0 auto; padding: var(--s6) var(--s6) var(--s8); }
.eyebrow {
  margin: 0;
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--gold);
}

/* ---------------------------------------------------------------- masthead */

.masthead {
  display: flex; align-items: center; justify-content: space-between; gap: var(--s5);
  padding-bottom: var(--s5);
  border-bottom: 1px solid var(--line);
}
.brand { display: flex; align-items: center; gap: var(--s3); }
.radar-mark {
  position: relative; display: inline-block; width: 38px; height: 38px; flex: none;
  border-radius: 50%; border: 1px solid var(--gold-line);
  background: radial-gradient(circle at 68% 32%, var(--gold) 0 2px, transparent 3px);
  box-shadow: inset 0 0 0 6px rgba(242, 193, 92, 0.03), 0 0 24px rgba(242, 193, 92, 0.08);
}
.radar-mark::before {
  content: ""; position: absolute; inset: 8px; border-radius: 50%;
  border: 1px solid rgba(242, 193, 92, 0.28);
}
.radar-mark::after {
  content: ""; position: absolute; inset: 16px; border-radius: 50%;
  background: var(--gold); box-shadow: 0 0 14px rgba(242, 193, 92, 0.6);
}
.brand-text { display: grid; gap: 1px; }
.wordmark { font-size: 18px; font-weight: 600; letter-spacing: -0.01em; }
.brand-sub {
  font-family: var(--font-mono); font-size: 10px; letter-spacing: 0.13em;
  text-transform: uppercase; color: var(--faint);
}
.mast-meta { display: flex; flex-wrap: wrap; gap: var(--s2); justify-content: flex-end; }
.pill {
  display: inline-flex; align-items: center; gap: 6px; white-space: nowrap;
  padding: 5px 10px; border: 1px solid var(--line); border-radius: 999px;
  background: rgba(17, 24, 35, 0.72); color: var(--muted);
  font-family: var(--font-mono); font-size: 11px; letter-spacing: 0.02em;
}
.pill-live { color: var(--mint); border-color: rgba(103, 224, 189, 0.28); }
.pill-live::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--mint); box-shadow: 0 0 10px var(--mint); }

/* ---------------------------------------------------------------- hero */

.hero { padding: var(--s7) 0 var(--s6); display: grid; gap: var(--s3); }
.hero h1 {
  max-width: 20ch;
  margin: var(--s2) 0 0;
  font-size: clamp(34px, 5.2vw, 58px);
  line-height: 1.04;
}
.hero h1 em { font-style: italic; color: var(--gold); }
.lede { max-width: 76ch; color: var(--ink-2); font-size: 16px; }
.lede.small { font-size: 14px; color: var(--muted); }

.stats {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: var(--s3);
  margin-top: var(--s5);
}
.stat {
  position: relative; overflow: hidden;
  display: grid; gap: var(--s1);
  padding: var(--s4) var(--s4) var(--s4);
  border: 1px solid var(--line); border-radius: var(--radius);
  background: linear-gradient(160deg, rgba(22, 32, 45, 0.92), rgba(13, 18, 25, 0.92));
}
.stat::before {
  content: ""; position: absolute; inset: 0 0 auto 0; height: 2px;
  background: linear-gradient(90deg, var(--gold), transparent 72%);
  opacity: 0.7;
}
.stat-label {
  font-family: var(--font-mono); font-size: 10px; letter-spacing: 0.12em;
  text-transform: uppercase; color: var(--faint);
}
.stat-value {
  font-family: var(--font-mono); font-size: clamp(22px, 2.4vw, 30px);
  font-weight: 500; line-height: 1.1; color: var(--ink);
  font-variant-numeric: tabular-nums;
}
.stat-sub { font-size: 12px; color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* ---------------------------------------------------------------- toolbar */

.toolbar {
  display: flex; flex-wrap: wrap; align-items: flex-end; gap: var(--s3);
  padding: var(--s4);
  border: 1px solid var(--line); border-radius: var(--radius);
  background: rgba(17, 24, 35, 0.78);
  margin-bottom: var(--s3);
}
.field { display: grid; gap: var(--s1); min-width: 0; }
.field > label, .field-label {
  font-family: var(--font-mono); font-size: 10px; letter-spacing: 0.1em;
  text-transform: uppercase; color: var(--faint);
}
.field-search { flex: 1 1 280px; }
.control, .reset {
  min-height: 38px; padding: 0 var(--s3);
  border: 1px solid var(--line-2); border-radius: var(--radius-sm);
  background: var(--bg-2); color: var(--ink);
}
.control:hover { border-color: var(--faint); }
.field-search .control { width: 100%; }
select.control { min-width: 150px; }
.check {
  display: inline-flex; align-items: center; gap: var(--s2);
  min-height: 38px; padding: 0 var(--s3);
  border: 1px solid var(--line-2); border-radius: var(--radius-sm);
  background: var(--bg-2); color: var(--ink-2); font-size: 13px; cursor: pointer;
}
.check input { accent-color: var(--gold); width: 15px; height: 15px; }
.segmented {
  display: inline-flex; gap: 3px; padding: 3px;
  border: 1px solid var(--line-2); border-radius: var(--radius-sm); background: var(--bg-2);
}
.seg-btn {
  min-height: 30px; padding: 0 var(--s3); border: 0; border-radius: 6px;
  background: transparent; color: var(--muted); font-size: 13px;
}
.seg-btn:hover { color: var(--ink); }
.seg-btn[aria-pressed="true"] { background: var(--gold); color: #17120a; font-weight: 600; }
.toolbar-tail { display: flex; align-items: center; gap: var(--s3); margin-left: auto; }
.result-count { color: var(--muted); font-family: var(--font-mono); font-size: 12px; white-space: nowrap; }
.reset { min-height: 38px; background: transparent; color: var(--muted); }
.reset:hover { color: var(--ink); border-color: var(--faint); }
.reset-lg { min-height: 40px; padding: 0 var(--s5); background: var(--gold); border-color: var(--gold); color: #17120a; font-weight: 600; }

/* ---------------------------------------------------------------- board */

.panel {
  overflow: hidden;
  border: 1px solid var(--line); border-radius: var(--radius-lg);
  background: var(--panel);
  box-shadow: var(--shadow);
}
.panel-inner { display: grid; }
.panel-head {
  display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between;
  gap: var(--s2) var(--s4);
  padding: var(--s4) var(--s5);
  border-bottom: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(22, 32, 45, 0.72), rgba(17, 24, 35, 0.2));
}
.panel-head h2 { font-size: 21px; }
.sub, .detail-sub { color: var(--muted); font-size: 12px; }
.panel-head .sub { max-width: 72ch; }

.table-wrap { max-height: min(74vh, 920px); overflow: auto; }
table { width: 100%; border-collapse: collapse; font-size: 14px; }
caption { caption-side: top; }
thead th {
  position: sticky; top: 0; z-index: 2;
  padding: 0; text-align: left; white-space: nowrap;
  background: var(--panel-2);
  box-shadow: inset 0 -1px 0 var(--line);
}
.sort-btn {
  display: inline-flex; align-items: center; gap: 5px;
  width: 100%; padding: var(--s3) var(--s3);
  border: 0; background: transparent; color: var(--faint);
  font-family: var(--font-mono); font-size: 10px; letter-spacing: 0.1em;
  text-transform: uppercase; text-align: left;
}
.sort-btn:hover { color: var(--ink-2); }
th[aria-sort="ascending"] .sort-btn, th[aria-sort="descending"] .sort-btn { color: var(--gold); }
th.col-implied .sort-btn, th.col-tvl .sort-btn, th.col-growth .sort-btn, th.col-age .sort-btn, th.col-mcap .sort-btn { justify-content: flex-end; }
.sort-arrow { font-size: 12px; line-height: 1; }
th.col-rank { padding: var(--s3) var(--s3); color: var(--faint); font-family: var(--font-mono); font-size: 10px; letter-spacing: 0.1em; text-transform: uppercase; }
tbody td {
  padding: var(--s3) var(--s3);
  border-bottom: 1px solid var(--line);
  vertical-align: middle;
}
tbody tr:last-child td { border-bottom: 0; }
tbody tr {
  cursor: pointer;
  transition: background 120ms ease;
}
tbody tr:hover { background: var(--panel-2); }
tbody tr:focus-visible { outline-offset: -2px; }
tbody tr[data-selected="true"] {
  background: var(--gold-soft);
  box-shadow: inset 3px 0 0 var(--gold);
}
.col-rank { width: 52px; }
.col-proto { min-width: 210px; }
.col-cat { min-width: 140px; }
.col-chains { min-width: 150px; }
.col-implied { min-width: 180px; }
.col-tvl, .col-growth, .col-age, .col-mcap { text-align: right; white-space: nowrap; }
.rank { font-family: var(--font-mono); font-size: 12px; color: var(--faint); font-variant-numeric: tabular-nums; }
.proto { display: grid; gap: 2px; }
.proto-name { display: flex; align-items: center; gap: var(--s2); min-width: 0; }
.proto-name b { font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.proto-slug { font-family: var(--font-mono); font-size: 11px; color: var(--faint); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.watch-tag {
  flex: none; padding: 1px 6px; border-radius: 999px;
  background: var(--gold-soft); border: 1px solid var(--gold-line);
  color: var(--gold); font-family: var(--font-mono); font-size: 9px; letter-spacing: 0.06em;
  text-transform: uppercase;
}
.tag {
  display: inline-block; max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  padding: 3px 8px; border-radius: 999px;
  border: 1px solid var(--line-2); background: var(--bg-2);
  color: var(--ink-2); font-size: 11px;
}
.chains { color: var(--muted); font-size: 12px; }
.num, .money { font-family: var(--font-mono); font-variant-numeric: tabular-nums; white-space: nowrap; }
.num { color: var(--ink-2); }
.money { color: var(--ink); font-weight: 500; }
.pos { color: var(--mint); }
.neg { color: var(--red); }
.flat { color: var(--muted); }
.col-age { color: var(--muted); font-size: 12px; }
.implied-cell { display: flex; align-items: center; justify-content: flex-end; gap: var(--s2); }
.bar {
  width: 92px; height: 5px; border-radius: 3px; overflow: hidden; flex: none;
  background: var(--line-2);
}
.bar i { display: block; height: 100%; border-radius: 3px; background: linear-gradient(90deg, rgba(242, 193, 92, 0.55), var(--gold)); }
.status-live {
  display: inline-flex; align-items: center; gap: 6px; white-space: nowrap;
  color: var(--mint); font-family: var(--font-mono); font-size: 11px;
}
.status-live::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: var(--mint); }

.empty { padding: var(--s8) var(--s5); text-align: center; display: grid; gap: var(--s3); justify-items: center; }
.empty h2 { font-size: 24px; }
.empty p { color: var(--muted); }

/* ---------------------------------------------------------------- method */

.method { margin-top: var(--s5); padding: var(--s6); border: 1px solid var(--line); border-radius: var(--radius-lg); background: var(--panel); }
.method-head { display: grid; gap: var(--s2); max-width: 88ch; }
.method-head h2 { font-size: 28px; }
.method-grid { display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(0, 0.9fr); gap: var(--s4); margin-top: var(--s5); }
.formula-card, .weights-card { padding: var(--s4); border: 1px solid var(--line); border-radius: var(--radius); background: var(--bg-2); }
.formula-card h3, .weights-card h3 { margin-bottom: var(--s3); font-size: 14px; }
.formula {
  margin: 0; padding: var(--s3);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--panel);
  color: var(--gold); font-family: var(--font-mono); font-size: 12.5px; line-height: 1.8;
  overflow-x: auto;
}
.weights { display: grid; grid-template-columns: 1fr 1fr; gap: var(--s2); }
.weight {
  display: flex; align-items: center; justify-content: space-between; gap: var(--s2);
  padding: 7px 10px; border: 1px solid var(--line); border-radius: var(--radius-sm);
  background: var(--panel); font-size: 12px;
}
.weight-label { color: var(--ink-2); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.weight-value { font-family: var(--font-mono); color: var(--gold); font-weight: 500; }
.weight-default { border-style: dashed; }
.model-notes { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: var(--s3); margin-top: var(--s4); }
.model-note { padding-top: var(--s3); border-top: 1px solid var(--line); }
.model-note h4 { font-size: 12px; color: var(--gold); margin-bottom: var(--s1); }
.model-note p { color: var(--muted); font-size: 12px; line-height: 1.55; }

/* ---------------------------------------------------------------- footer */

.footer {
  display: flex; flex-wrap: wrap; justify-content: space-between; gap: var(--s3);
  margin-top: var(--s6); padding-top: var(--s4);
  border-top: 1px solid var(--line);
  color: var(--muted); font-size: 12px;
}
.footer strong { color: var(--ink-2); }
.footer-note { max-width: 82ch; }

/* ---------------------------------------------------------------- detail drawer */

.detail {
  position: fixed; inset: 0 0 0 auto;
  width: min(640px, 100vw); height: 100%; max-width: 100%; max-height: 100%;
  margin: 0; padding: 0; border: 0; border-left: 1px solid var(--line-2);
  background: var(--bg-2); color: var(--ink);
  overflow-y: auto; box-shadow: -40px 0 90px rgba(0, 0, 0, 0.55);
}
.detail:not([open]) { display: none; }
.detail[open] { animation: drawer-in 200ms cubic-bezier(0.2, 0.7, 0.2, 1); }
.detail::backdrop { background: rgba(4, 6, 10, 0.72); backdrop-filter: blur(2px); }
@keyframes drawer-in { from { transform: translateX(28px); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
.detail-inner { padding: var(--s5) var(--s5) var(--s7); display: grid; gap: var(--s5); }
.detail-top {
  position: sticky; top: 0; z-index: 3;
  display: flex; align-items: flex-start; justify-content: space-between; gap: var(--s4);
  padding: var(--s5) 0 var(--s4);
  margin: calc(-1 * var(--s5)) 0 0;
  background: linear-gradient(180deg, var(--bg-2) 74%, rgba(13, 18, 25, 0));
  border-bottom: 1px solid var(--line);
}
.detail-heading { min-width: 0; display: grid; gap: var(--s2); }
.detail-heading h2 { font-size: clamp(26px, 4vw, 34px); line-height: 1.08; overflow-wrap: anywhere; }
.icon-btn {
  flex: none; min-height: 34px; padding: 0 var(--s3);
  border: 1px solid var(--line-2); border-radius: var(--radius-sm);
  background: var(--panel); color: var(--ink-2); font-size: 12px;
}
.icon-btn:hover { border-color: var(--gold-line); color: var(--gold); }
.chips { display: flex; flex-wrap: wrap; gap: 6px; }
.chip {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 2px 8px; border-radius: 999px;
  border: 1px solid var(--line-2); background: var(--panel);
  color: var(--muted); font-family: var(--font-mono); font-size: 10.5px;
}
.chip-cat { color: var(--ink-2); }
.chip-gold { color: var(--gold); border-color: var(--gold-line); background: var(--gold-soft); }
.detail-implied {
  display: grid; gap: var(--s1);
  padding: var(--s4) var(--s5);
  border: 1px solid var(--gold-line); border-radius: var(--radius);
  background: linear-gradient(150deg, var(--gold-soft), rgba(17, 24, 35, 0.5) 70%);
}
.big-money {
  font-family: var(--font-mono); font-size: clamp(32px, 6vw, 46px); font-weight: 500;
  line-height: 1; color: var(--gold); font-variant-numeric: tabular-nums;
}
.detail-facts { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: var(--s2); }
.fact {
  display: grid; gap: 2px; padding: var(--s3);
  border: 1px solid var(--line); border-radius: var(--radius-sm); background: var(--panel);
}
.fact span { color: var(--faint); font-family: var(--font-mono); font-size: 9.5px; letter-spacing: 0.08em; text-transform: uppercase; }
.fact b { font-family: var(--font-mono); font-size: 14px; font-weight: 500; color: var(--ink); font-variant-numeric: tabular-nums; }
.detail-section { display: grid; gap: var(--s3); }
.detail-section h3 { font-size: 15px; }
.detail-section h3::before { content: ""; display: inline-block; width: 14px; height: 2px; margin-right: 8px; vertical-align: middle; background: var(--gold); }
.breakdown { display: grid; border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; }
.breakdown-row {
  display: grid; grid-template-columns: minmax(110px, 0.8fr) minmax(0, 1.5fr) auto;
  gap: var(--s3); align-items: baseline;
  padding: var(--s3) var(--s4);
  border-bottom: 1px solid var(--line);
  background: var(--panel);
}
.breakdown-row:last-child { border-bottom: 0; }
.breakdown-row .factor { color: var(--faint); font-family: var(--font-mono); font-size: 10px; letter-spacing: 0.08em; text-transform: uppercase; }
.breakdown-row .detail-text { color: var(--ink-2); font-size: 13px; overflow-wrap: anywhere; }
.breakdown-row .mult { color: var(--gold); font-family: var(--font-mono); font-size: 13px; white-space: nowrap; }
.breakdown-row.total { background: var(--panel-2); }
.breakdown-row.total .factor { color: var(--gold); }
.breakdown-row.total .mult { color: var(--gold); font-weight: 600; }
.why {
  padding: var(--s4);
  border-left: 2px solid var(--gold);
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  background: var(--gold-soft);
  color: var(--ink-2); font-size: 13.5px; line-height: 1.65;
}
.plan { list-style: none; margin: 0; padding: 0; display: grid; gap: var(--s3); }
.plan-step { display: grid; grid-template-columns: 30px minmax(0, 1fr); gap: var(--s3); }
.plan-num {
  display: grid; place-items: center; width: 30px; height: 30px;
  border-radius: 50%; border: 1px solid var(--gold-line); background: var(--gold-soft);
  color: var(--gold); font-family: var(--font-mono); font-size: 12px;
}
.plan-body { display: grid; gap: var(--s2); padding-bottom: var(--s3); border-bottom: 1px solid var(--line); }
.plan-step:last-child .plan-body { border-bottom: 0; }
.plan-action { color: var(--ink); font-size: 13.5px; line-height: 1.55; }
.chip-cost { color: var(--gold); border-color: var(--gold-line); background: var(--gold-soft); }
.chip-time { color: var(--blue); border-color: rgba(133, 184, 255, 0.28); background: rgba(133, 184, 255, 0.1); }
.detail-note { color: var(--faint); font-size: 11.5px; line-height: 1.6; }

